SELECT bool_or(invalid) FROM (SELECT EXISTS(SELECT sheet_id FROM _duxcel_workspace.source_versions GROUP BY sheet_id HAVING count(*)>1024) AS invalid UNION ALL SELECT EXISTS(SELECT 1 FROM _duxcel_workspace.source_versions WHERE source_reference IS NULL OR octet_length(encode(source_reference))>65536 OR contains(source_reference,chr(0)) OR octet_length(definition)>=262144) AS invalid UNION ALL SELECT EXISTS(SELECT 1 FROM _duxcel_workspace.sheets WHERE path IS NULL OR octet_length(encode(path))>65536 OR contains(path,chr(0))) AS invalid UNION ALL SELECT EXISTS(SELECT 1 FROM _duxcel_workspace.table_sources WHERE path IS NULL OR octet_length(encode(path))>65536 OR contains(path,chr(0))) AS invalid UNION ALL SELECT EXISTS(SELECT sheet_id FROM _duxcel_workspace.format_scopes GROUP BY sheet_id HAVING count(*)>512) AS invalid UNION ALL SELECT EXISTS(SELECT 1 FROM _duxcel_workspace.format_scopes WHERE definition IS NULL OR octet_length(definition)>=262144) AS invalid UNION ALL SELECT EXISTS(SELECT sheet_id,position FROM _duxcel_workspace.format_guards GROUP BY sheet_id,position HAVING count(*)>33) AS invalid UNION ALL SELECT EXISTS(SELECT sheet_id,position FROM _duxcel_workspace.format_records GROUP BY sheet_id,position HAVING count(*)>20000) AS invalid UNION ALL SELECT EXISTS(SELECT sheet_id,position FROM _duxcel_workspace.format_fields GROUP BY sheet_id,position HAVING count(*)>16384) AS invalid) checks
